local currentArtIdx = 1 -- Default to 1st artwork
local scrollY = 0
local scrollX = 0

-- Touch Button Storage
local TouchButtons = {}
local function clearButtons() TouchButtons = {} end
local function registerButton(id, x, y, w, h, label, fg, bg)
    table.insert(TouchButtons, {
        id = id, x1 = x, y1 = y, x2 = x + w - 1, y2 = y + h - 1,
        w = w, h = h, label = label, fg = fg or "0", bg = bg or "7"
    })
end

local function drawButtons()
    for _, btn in ipairs(TouchButtons) do
        display.setCursorPos(btn.x1, btn.y1)
        display.setBackgroundColor(colors[btn.bg] or colors.gray)
        display.setTextColor(colors[btn.fg] or colors.white)
        display.write(btn.label)
    end
end

local function checkButtonClicked(clickX, clickY)
    for _, btn in ipairs(TouchButtons) do
        if clickX >= btn.x1 and clickX <= btn.x2 and clickY >= btn.y1 and clickY <= btn.y2 then
            return btn.id
        end
    end
    return nil
end

local function getDisplayRows(artIdx)
    local art = GALLERY[artIdx] or GALLERY[1]
    return art.rows
end

local function nextArt()
    currentArtIdx = currentArtIdx + 1
    if currentArtIdx > #GALLERY then currentArtIdx = 1 end
    scrollY = 0
    scrollX = 0
end

local function prevArt()
    currentArtIdx = currentArtIdx - 1
    if currentArtIdx < 1 then currentArtIdx = #GALLERY end
    scrollY = 0
    scrollX = 0
end

-- ============================================================================
-- RENDER WITH GLOWING PICTURE FRAME & CLEAN NAVIGATION
-- ============================================================================
local statusMsg = ""
local statusTimer = 0

local function playChime(success)
    local speaker = peripheral.find("speaker")
    if speaker then
        if success then
            pcall(function()
                speaker.playNote("chime", 1.0, 12)
                sleep(0.05)
                speaker.playNote("chime", 1.0, 16)
            end)
        else
            pcall(function()
                speaker.playNote("bass", 1.0, 4)
            end)
        end
    end
end

local function printArt()
    local art = GALLERY[currentArtIdx] or GALLERY[1]
    local printer = peripheral.find("printer")
    
    if not printer then
        -- Export / Save to file fallback
        local cleanName = string.gsub(string.lower(art.name), "[^%w]+", "_")
        local filename = "printout_" .. cleanName .. ".txt"
        local f = fs.open(filename, "w")
        if f then
            f.writeLine("========================================")
            f.writeLine("  " .. string.upper(art.name))
            f.writeLine("========================================")
            for _, r in ipairs(art.rows) do
                f.writeLine(r.ch)
            end
            f.close()
            statusMsg = "[SAVED TO " .. filename .. " (NO PRINTER)]"
            playChime(true)
        else
            statusMsg = "[ERR: NO PRINTER CONNECTED]"
            playChime(false)
        end
        statusTimer = os.epoch("utc") + 4000
        return
    end
    
    if printer.getPaperLevel() == 0 then
        statusMsg = "[PRINTER ERR: INSERT PAPER]"
        playChime(false)
        statusTimer = os.epoch("utc") + 4000
        return
    end
    
    if printer.getInkLevel() == 0 then
        statusMsg = "[PRINTER ERR: INSERT INK/DYE]"
        playChime(false)
        statusTimer = os.epoch("utc") + 4000
        return
    end
    
    local ok, err = pcall(function()
        printer.newPage()
        printer.setPageTitle("Art #" .. currentArtIdx .. " " .. string.sub(art.name, 1, 15))
        
        local pW, pH = 25, 20
        printer.setCursorPos(1, 1)
        printer.write("#" .. currentArtIdx .. " " .. string.sub(art.name, 1, 21))
        
        for y = 1, math.min(#art.rows, 19) do
            local row = art.rows[y]
            printer.setCursorPos(1, y + 1)
            printer.write(string.sub(row.ch, 1, pW))
        end
        
        printer.endPage()
    end)
    
    if ok then
        statusMsg = "[PRINT SUCCESS: PAGE PRINTED!]"
        playChime(true)
    else
        statusMsg = "[PRINT FAILED: " .. tostring(err) .. "]"
        playChime(false)
    end
    statusTimer = os.epoch("utc") + 4000
end

local function render()
    local screenW, screenH = display.getSize()
    clearButtons()
    
    local art = GALLERY[currentArtIdx] or GALLERY[1]
    local rows = getDisplayRows(currentArtIdx)
    local artW = #rows[1].ch
    local artH = #rows
    
    local maxScrollY = math.max(0, artH - (screenH - 4))
    local maxScrollX = math.max(0, artW - (screenW - 4))
    scrollY = math.min(scrollY, maxScrollY)
    scrollY = math.max(0, scrollY)
    scrollX = math.min(scrollX, maxScrollX)
    scrollX = math.max(0, scrollX)
    
    display.setBackgroundColor(colors.black)
    display.clear()
    
    -- 1. Premium Header Navigation Bar
    display.setCursorPos(1, 1)
    display.setBackgroundColor(colors.gray)
    display.setTextColor(colors.white)
    display.write(string.rep(" ", screenW))
    
    -- Navigation Buttons & PRINT Button
    local prevBtnW = 10
    local nextBtnW = 10
    local printBtnW = 9
    
    registerButton("BTN_PREV", 2, 1, prevBtnW, 1, "[ < PREV ]", "white", "blue")
    registerButton("BTN_PRINT", screenW - nextBtnW - printBtnW - 2, 1, printBtnW, 1, "[ PRINT ]", "yellow", "gray")
    registerButton("BTN_NEXT", screenW - nextBtnW, 1, nextBtnW, 1, "[ NEXT > ]", "white", "blue")
    
    -- Centered Title
    local titleStr = string.format("#%d/%d  %s", currentArtIdx, #GALLERY, art.name)
    local maxTitleSpace = screenW - (prevBtnW + nextBtnW + printBtnW + 8)
    if #titleStr > maxTitleSpace then
        titleStr = string.sub(titleStr, 1, maxTitleSpace)
    end
    local titleX = math.max(prevBtnW + 3, math.floor((screenW - #titleStr) / 2) - 2)
    display.setCursorPos(titleX, 1)
    display.setTextColor(colors.yellow)
    display.write(titleStr)
    
    -- 2. Art Drawing Area & Picture Frame
    local startX = math.max(3, math.floor((screenW - artW) / 2) + 1 - scrollX)
    local startYOffset = 3
    if artH < (screenH - 4) then
        startYOffset = 3 + math.floor(((screenH - 4) - artH) / 2)
    end
    
    local startRow = scrollY + 1
    local endRow = math.min(artH, startRow + (screenH - 5))
    local actualRenderedRows = endRow - startRow + 1
    
    -- Picture Frame Coordinates
    local fLeft = math.max(1, startX - 1)
    local fRight = math.min(screenW, startX + artW)
    local fTop = math.max(2, startYOffset - 1)
    local fBottom = math.min(screenH - 1, startYOffset + actualRenderedRows)
    local fWidth = fRight - fLeft + 1
    
    -- Draw Glowing Neon Picture Frame (Top & Bottom)
    if fWidth >= 3 then
        local borderLine = "+" .. string.rep("=", fWidth - 2) .. "+"
        display.setTextColor(colors.cyan)
        display.setBackgroundColor(colors.black)
        
        if fTop >= 2 then
            display.setCursorPos(fLeft, fTop)
            display.write(borderLine)
        end
        if fBottom <= screenH - 1 then
            display.setCursorPos(fLeft, fBottom)
            display.write(borderLine)
        end
    end
    
    -- Draw Picture Rows & Frame Sides
    for rowIdx = startRow, endRow do
        local rowData = rows[rowIdx]
        local drawY = startYOffset + (rowIdx - startRow)
        
        -- Frame Vertical Sides in Glowing Cyan
        display.setTextColor(colors.cyan)
        display.setBackgroundColor(colors.black)
        if fLeft >= 1 and drawY >= 2 and drawY < screenH then
            display.setCursorPos(fLeft, drawY)
            display.write("|")
        end
        if fRight <= screenW and drawY >= 2 and drawY < screenH then
            display.setCursorPos(fRight, drawY)
            display.write("|")
        end
        
        -- Photo Content (Vibrant 16-Color Blit)
        local chStr = rowData.ch
        local fgStr = rowData.fg
        local bgStr = rowData.bg
        
        local drawPosX = startX
        if drawPosX < 2 then
            local clip = 2 - drawPosX + 1
            chStr = string.sub(chStr, clip)
            fgStr = string.sub(fgStr, clip)
            bgStr = string.sub(bgStr, clip)
            drawPosX = 2
        end
        if #chStr > screenW - drawPosX then
            local maxLen = screenW - drawPosX
            chStr = string.sub(chStr, 1, maxLen)
            fgStr = string.sub(fgStr, 1, maxLen)
            bgStr = string.sub(bgStr, 1, maxLen)
        end
        
        if #chStr > 0 and drawPosX < screenW and drawY < screenH then
            display.setCursorPos(drawPosX, drawY)
            pcall(function()
                display.blit(chStr, fgStr, bgStr)
            end)
        end
    end
    
    -- 3. Bottom Footer Status Bar
    display.setCursorPos(1, screenH)
    display.setBackgroundColor(colors.gray)
    display.setTextColor(colors.lightBlue)
    display.write(string.rep(" ", screenW))
    
    local footerText = " [ < / > ] Switch Photo    [ P ] Print    [ 1-9 / 0 ] Direct Select    [ Q ] Exit "
    if os.epoch("utc") < statusTimer and #statusMsg > 0 then
        footerText = statusMsg
        display.setTextColor(colors.yellow)
    end
    display.setCursorPos(math.max(2, math.floor((screenW - #footerText) / 2) + 1), screenH)
    display.write(footerText)
    
    drawButtons()
end

local function main()
    while true do
        render()
        local event, p1, p2, p3 = os.pullEvent()
        
        if event == "key" then
            if p1 == keys.n or p1 == keys.right or p1 == keys.d or p1 == keys.tab or p1 == keys.space or p1 == keys.rightBracket then
                nextArt()
            elseif p1 == keys.left or p1 == keys.a or p1 == keys.leftBracket then
                prevArt()
            elseif p1 == keys.p then
                printArt()
            -- Quick Number Select
            elseif p1 == keys.one then currentArtIdx = 1; scrollY = 0; scrollX = 0
            elseif p1 == keys.two then currentArtIdx = 2; scrollY = 0; scrollX = 0
            elseif p1 == keys.three then currentArtIdx = 3; scrollY = 0; scrollX = 0
            elseif p1 == keys.four then currentArtIdx = 4; scrollY = 0; scrollX = 0
            elseif p1 == keys.five then currentArtIdx = 5; scrollY = 0; scrollX = 0
            elseif p1 == keys.six then currentArtIdx = 6; scrollY = 0; scrollX = 0
            elseif p1 == keys.seven then currentArtIdx = 7; scrollY = 0; scrollX = 0
            elseif p1 == keys.eight then currentArtIdx = 8; scrollY = 0; scrollX = 0
            elseif p1 == keys.nine then currentArtIdx = 9; scrollY = 0; scrollX = 0
            elseif p1 == keys.zero then currentArtIdx = 10; scrollY = 0; scrollX = 0
            elseif p1 == keys.q or p1 == keys.escape then
                break
            end
            
        elseif event == "mouse_scroll" then
            if p1 > 0 then nextArt() else prevArt() end
            
        elseif event == "mouse_click" or event == "monitor_touch" then
            local mx, my = p2, p3
            local cid = checkButtonClicked(mx, my)
            
            if cid == "BTN_PREV" then
                prevArt()
            elseif cid == "BTN_NEXT" then
                nextArt()
            elseif cid == "BTN_PRINT" then
                printArt()
            else
                local screenW, _ = display.getSize()
                if mx < math.floor(screenW / 2) then
                    prevArt()
                else
                    nextArt()
                end
            end
        end
    end
    
    restorePalette()
    display.setBackgroundColor(colors.black)
    display.setTextColor(colors.white)
    display.clear()
    display.setCursorPos(1, 1)
    if isMonitor then
        display.write("Art Gallery closed.")
    else
        print("Art Gallery closed.")
    end
end

local ok, err = pcall(main)
if not ok then
    restorePalette()
    display.setBackgroundColor(colors.black)
    display.setTextColor(colors.red)
    display.clear()
    display.setCursorPos(1, 1)
    display.write("Error: " .. tostring(err))
    term.setCursorPos(1, 1)
    print("Error: " .. tostring(err))
end
